/* Local composition UI: structured page state, no publishing or AI service. */
const composerLibrary=['Announcement bar','Hero','Logo cloud','Feature grid','Selected work','Testimonials','Pricing','Lead form','FAQ','Footer'];
let composerTab='canvas',composerStarter='saas-modern',composerBinding='CRM. Lead capture';
const sectionName=x=>typeof x==='string'?x:x.type;
const starter=id=>siteTemplates[id]||siteTemplates['saas-modern'];
function loadStarter(id){const s=starter(id);composerStarter=id;activeTemplate=id;hero=s.heading;schema.template=id;schema.theme.primaryColor=s.color;schema.theme.font=s.font;composerBinding=s.binding;schema.sections=s.sections.map((type,i)=>({type,variant:i===1?s.variant:undefined,heading:i===1?hero:undefined}));selected='Hero'}
function pagePreview(){const s=starter(composerStarter),blocks=schema.sections.filter(x=>!['Navbar','Hero','Footer'].includes(sectionName(x))),heroSection=schema.sections.find(x=>sectionName(x)==='Hero')||{};return `<div class="composer-preview"><div class="browser-chrome">● ● ● <span>Preview. ${schema.sections.length} blocks</span></div><div class="preview-page" style="--brand:${schema.theme.primaryColor};font-family:var(--nx-font-body);text-align:${heroSection.variant==='Left aligned'?'left':'center'}"><nav><strong>${s.brand}</strong><span>Product &nbsp; Stories &nbsp; Contact</span></nav>${schema.sections.some(x=>sectionName(x)==='Hero')?`<header><small>${s.label}</small><h1>${esc(hero)}</h1><p>${s.body}</p><button>${s.cta} </button></header>`:''}<div class="preview-blocks">${blocks.map((x,i)=>`<article class="tone-${i%3}"><small>${sectionName(x)}</small><b>${sectionName(x)==='Testimonials'?'Trusted by ambitious teams':sectionName(x)==='Lead form'?'Turn interest into a useful conversation':'A story built around your customer'}</b><i></i></article>`).join('')}</div>${schema.sections.some(x=>sectionName(x)==='Footer')?`<footer>${s.brand}<span>Built as a Nexus concept</span></footer>`:''}</div></div>`}
function blueprint(){return `<div class="blueprint-card"><div>Structured page blueprint <small>Frontend preview</small></div><pre>${esc(JSON.stringify({starter:composerStarter==='blank'?null:composerStarter,design:{color:schema.theme.primaryColor,font:schema.theme.font},binding:composerBinding,sections:schema.sections.map((x,i)=>({id:`section_${i+1}`,type:sectionName(x)}))},null,2))}</pre></div>`}
function websites(){const templ=tab==='Templates',items=templ?Object.entries(siteTemplates):[['saas-modern',{...siteTemplates['saas-modern'],name:'Acme main website',category:'acme.nexus.site'}],['gather',{...siteTemplates.gather,name:'Growth Masterclass',category:'acme.nexus.site/masterclass'}],['product',{...siteTemplates.product,name:'Product launch',category:'Draft. Not published'}]];return head(templ?'Choose a starting point':'Your websites',templ?'Start blank, pick a starter kit, then compose approved sections into a page that fits your business.':'Your digital storefront, connected to the rest of your business.',btn('+ Create website','new-site',true))+tabs(['Websites','Templates'])+(templ?`<section class="composer-intro"><div><span>Composable website builder</span><h2>Start with a direction. Make it your own.</h2><p>Starter kits are optional. Build a page from approved sections, shared design tokens, and structured business bindings.</p></div><button data-starter="blank"><b>＋</b><strong>Start from a blank page</strong><small>Add only the sections your story needs.</small></button></section>`:'')+`<div class="sites-grid">${items.map(([id,x],i)=>`<div class="card template-card"><div class="site-cover template-${id}" style="--template-color:${x.color}"><div class="mini-site"><div class="mini-nav"><strong>${x.brand}</strong><span>About &nbsp; Contact</span></div><span class="mini-kicker">${x.label}</span><h3>${x.heading}</h3><p>${templ?x.category:'Composable website'}</p><button data-starter="${id}">${templ?'Use as a starting point ':'Edit blueprint '}</button></div></div><div class="site-info"><div><h3>${x.name}</h3><p>${x.category}</p></div>${badge(templ?'Starter kit':i===2?'Draft':'Published',i===2?'':'green')}</div><div class="template-meta"><span>${x.sections.length} suggested sections</span><button class="btn" data-starter="${id}">${templ?'Open composer ':'Edit website '}</button></div></div>`).join('')}</div>`}
function builder(){const s=starter(composerStarter),current=schema.sections.find(x=>sectionName(x)===selected)||schema.sections[0];return head('Website composer','Compose a connected customer experience one structured section at a time.',btn(' All websites','go-website')+btn('Preview','site-preview')+btn('Publish','publish',true))+`<div class="composer-top"><div>${['canvas','design','review'].map((x,i)=>`<button class="${composerTab===x?'active':''}" data-composer-tab="${x}">${i+1}. ${x==='canvas'?'Compose':x==='design'?'Design system':'Review'}</button>`).join('')}</div><p>Starting point <button data-composer-action="starter">${composerStarter==='blank'?'Blank page':s.name} ⌄</button></p></div><div class="composer-layout"><aside><label>Page blueprint <b>${schema.sections.length}</b></label>${schema.sections.map((x,i)=>`<button class="blueprint-section ${selected===sectionName(x)?'selected':''}" data-blueprint-section="${sectionName(x)}"><i>${String(i+1).padStart(2,'0')}</i><strong>${sectionName(x)}</strong><small>${sectionName(x)==='Hero'?'Message':sectionName(x)==='Lead form'?'CRM':'Section'}</small></button>`).join('')}<button class="add-block" data-composer-action="library">＋ Add section</button><p>Every block has a defined purpose, safe variants, and a clear owner.</p></aside><main>${composerTab==='review'?blueprint()+`<div class="review-note"><b>Ready to review</b><h3>One page, a clear schema.</h3><p>Sections, theme tokens, and the business binding are represented together before publication.</p></div>`:pagePreview()}</main><aside class="inspector">${composerTab==='design'?`<label>Design tokens</label><h3>One visual language</h3><p>These values apply consistently across the page preview.</p><label>Brand color<input type="color" id="brand-color" value="${schema.theme.primaryColor}"></label><label>Type family<select id="font" class="input"><option ${schema.theme.font==='Manrope'?'selected':''}>Manrope</option><option ${schema.theme.font==='DM Sans'?'selected':''}>DM Sans</option><option ${schema.theme.font==='Arial'?'selected':''}>Arial</option></select></label>`:composerTab==='review'?`<label>Connected data</label><h3>One safe handoff</h3><p>Choose where this page’s primary conversion signal should appear.</p><label>Business binding<select id="composer-binding" class="input"><option ${composerBinding==='CRM. Lead capture'?'selected':''}>CRM. Lead capture</option><option ${composerBinding==='Webinars. Registration'?'selected':''}>Webinars. Registration</option><option ${composerBinding==='Billing. Pricing plans'?'selected':''}>Billing. Pricing plans</option></select></label><div class="binding">Website ${composerBinding}</div><button class="ai-button" data-composer-action="ai">✦ Ask AI to propose a change</button><small>No integrations or publishing are connected in this frontend blueprint.</small>`:`<label>Section settings</label><h3>${sectionName(current)}</h3><p>${sectionName(current)==='Hero'?'Define the promise visitors see first.':'Use this block to move the story forward.'}</p>${sectionName(current)==='Hero'?`<label>Heading<textarea id="hero-input" class="input" rows="4">${esc(hero)}</textarea></label><label>Layout<select id="variant" class="input"><option ${current.variant==='Centered'?'selected':''}>Centered</option><option ${current.variant==='Left aligned'?'selected':''}>Left aligned</option></select></label>`:`<div class="setting">Variant <button>Editorial cards ⌄</button></div>`}<button class="remove" data-composer-action="remove" ${['Navbar','Footer'].includes(sectionName(current))?'disabled':''}>Remove section</button><button class="ai-button" data-composer-action="ai">✦ Ask AI to propose a change</button>`}</aside></div>`}
function library(){modal('Add an approved section',`<p>Use reusable sections rather than a fixed layout. You can review and remove them before publication.</p><div class="library">${composerLibrary.map(x=>`<button data-library-section="${x}"><small>${x==='Pricing'||x==='Lead form'?'CONVERSION':x==='Testimonials'||x==='Logo cloud'?'PROOF':'NARRATIVE'}</small><strong>${x}</strong><span>＋</span></button>`).join('')}</div>`)}
function starters(){modal('Choose a starting point',`<p>A starter kit accelerates the first draft. The page remains fully composable.</p><div class="library">${[['blank',{name:'Blank page',category:'Begin with an empty blueprint.'}],...Object.entries(siteTemplates)].map(([id,s])=>`<button data-starter="${id}"><strong>${s.name}</strong><small>${s.category}</small></button>`).join('')}</div>`)}
function aiProposal(){modal('AI change proposal',`<p>AI drafts structured changes for review. Nothing is applied until you choose it.</p><div class="proposal"><small>Proposed diff</small><strong>Add proof after the feature grid</strong><p>Insert a Testimonials block and keep the existing CRM conversion binding.</p><code>+ sections[4] = { type: "Testimonials" }</code></div>`,`<button class="btn" data-composer-action="dismiss">Keep editing</button><button class="btn primary" data-composer-action="apply">Apply proposal</button>`)}
function selectTemplate(id){loadStarter(id);page='builder';location.hash='builder';render()}
document.addEventListener('click',e=>{const t=e.target.closest('[data-starter],[data-composer-action],[data-composer-tab],[data-blueprint-section],[data-library-section]');if(!t)return;if(t.dataset.starter!==undefined){if(t.dataset.starter==='blank'){loadStarter('saas-modern');composerStarter='blank';schema.sections=[{type:'Navbar'},{type:'Hero',variant:'Centered',heading:hero},{type:'Footer'}]}else loadStarter(t.dataset.starter);page='builder';location.hash='builder';close();render();return}if(t.dataset.composerTab){composerTab=t.dataset.composerTab;renderContent();return}if(t.dataset.blueprintSection){selected=t.dataset.blueprintSection;composerTab='canvas';renderContent();return}if(t.dataset.librarySection){schema.sections.splice(Math.max(1,schema.sections.length-1),0,{type:t.dataset.librarySection});selected=t.dataset.librarySection;close();composerTab='canvas';renderContent();toast(`${selected} added to the blueprint.`);return}if(t.dataset.composerAction==='library')return library();if(t.dataset.composerAction==='starter')return starters();if(t.dataset.composerAction==='ai')return aiProposal();if(t.dataset.composerAction==='dismiss')return close();if(t.dataset.composerAction==='apply'){if(!schema.sections.some(x=>sectionName(x)==='Testimonials'))schema.sections.splice(Math.max(1,schema.sections.length-1),0,{type:'Testimonials'});close();renderContent();toast('Proposal applied to this preview.');return}if(t.dataset.composerAction==='remove'){const i=schema.sections.findIndex(x=>sectionName(x)===selected);if(i>=0&&!['Navbar','Footer'].includes(selected)){schema.sections.splice(i,1);selected='Hero';renderContent();toast('Section removed from the blueprint.')}}});
document.addEventListener('input',e=>{if(e.target.id==='hero-input'){hero=e.target.value;const h=schema.sections.find(x=>sectionName(x)==='Hero');if(h)h.heading=hero;const n=document.querySelector('.preview-page h1');if(n)n.textContent=hero}if(e.target.id==='brand-color'){schema.theme.primaryColor=e.target.value;const n=document.querySelector('.preview-page');if(n)n.style.setProperty('--brand',schema.theme.primaryColor)}if(e.target.id==='font'){schema.theme.font=e.target.value;const n=document.querySelector('.preview-page');if(n)n.style.fontFamily=schema.theme.font}if(e.target.id==='variant'){const h=schema.sections.find(x=>sectionName(x)==='Hero');if(h)h.variant=e.target.value;const n=document.querySelector('.preview-page');if(n)n.style.textAlign=e.target.value==='Left aligned'?'left':'center'}if(e.target.id==='composer-binding')composerBinding=e.target.value});
loadStarter(activeTemplate);
